from mk import *
from lib import fbd
STRICT["on"] = True
import math
GM = 10 * 6.4e6 ** 2; m = 1e3
R1 = 3 * GM * m / (8 * 6e9); T1 = 2 * math.pi * math.sqrt(R1 ** 3 / GM); Eup = GM * m * (1 / 6.4e6 - 1 / (2 * R1))

E(id="bagrut-1982-q3", year=1982, label="1982 שאלה 3", topic="gravitation", sub="grav-energy", diff=4,
  stem=r"לוויין שמסתו $m = 10^3\,\text{kg}$ נע סביב כדור הארץ במסלול מעגלי שרדיוסו $R_1$, וזמן המחזור שלו $T_1$. כדי להעלות אותו למסלול מעגלי שרדיוסו $R_2$, גדול יותר, צריך אנרגיה של $\Delta E = 6 \times 10^9\,\text{J}$. זמן המחזור במסלול החדש $T_2$. נתון: על פני כדור הארץ $g = 10\,\text{m/s}^2$, ורדיוס כדור הארץ $6400\,\text{km}$.",
  parts=[
    P("א", r"היחס בין זמני המחזור הוא $\frac{T_2}{T_1} = 8$. מה הרדיוס $R_1$ של המסלול הראשון?", num(R1, "m"), ["principle", "algebra"], [
        S(r"החוק השלישי של קפלר", r"היחס בין הרדיוס בחזקה שלישית לזמן המחזור בריבוע זהה לכל הלוויינים של כדור הארץ", r"\frac{R_2^3}{T_2^2} = \frac{R_1^3}{T_1^2} \;\Rightarrow\; \left(\frac{R_2}{R_1}\right)^3 = 8^2 = 64 \;\Rightarrow\; R_2 = 4R_1", eq=r"\frac{r^3}{T^2} = \frac{GM}{4\pi^2}"),
        S(r"האנרגיה של לוויין במסלול מעגלי", r"מהמשוואה של הכוח אל המרכז, האנרגיה הקינטית היא חצי מגודל האנרגיה הפוטנציאלית. מחברים את שתיהן", r"\tfrac{1}{2}mv^2 = \frac{GMm}{2R} \;\Rightarrow\; E = \frac{GMm}{2R} - \frac{GMm}{R} = -\frac{GMm}{2R}", eq=r"U = -\frac{GMm}{r}"),
        S(r"ההפרש בין המסלולים", r"האנרגיה שצריך היא האנרגיה במסלול החדש פחות האנרגיה בישן", r"\Delta E = -\frac{GMm}{2 \cdot 4R_1} + \frac{GMm}{2R_1} = \frac{3GMm}{8R_1}"),
        S(r"פותרים", r"מכפלת הקבוע במסת כדור הארץ שווה לתאוצת הכובד כפול ריבוע הרדיוס", r"R_1 = \frac{3 \cdot 4.1 \times 10^{14} \cdot 10^3}{8 \cdot 6 \times 10^9} \approx 2.56 \times 10^7\,\text{m}", eq=r"g^* = \frac{GM}{r^2}"),
    ], r"$\approx 2.56 \times 10^7\,\text{m}$", key=r"2.56×10^7 m"),
    P("ב", r"מה זמן המחזור $T_1$ של הלוויין במסלול הראשון?", num(T1, "s"), ["principle"], [
        S(r"זמן מחזור במסלול מעגלי", r"מהחוק השלישי של קפלר, מבודדים את זמן המחזור", r"T_1 = 2\pi\sqrt{\frac{R_1^3}{GM}} = 2\pi\sqrt{\frac{(2.56 \times 10^7)^3}{4.1 \times 10^{14}}} \approx 40200\,\text{s}", eq=r"\frac{r^3}{T^2} = \frac{GM}{4\pi^2}"),
    ], r"$\approx 40200\,\text{s}$", key=r"40200 s"),
    P("ג", r"כמה אנרגיה היה צריך כדי להעלות את הלוויין מכן השיגור על פני כדור הארץ למסלול הראשון?", num(Eup, "J"), ["principle"], [
        S(r"על פני כדור הארץ", r"הלוויין עומד, ולכן יש לו רק אנרגיה פוטנציאלית. מזניחים את הסיבוב של כדור הארץ", r"E_0 = -\frac{GMm}{R}", eq=r"U = -\frac{GMm}{r}"),
        S(r"במסלול", r"האנרגיה של לוויין במסלול מעגלי, מהסעיף הראשון", r"E_1 = -\frac{GMm}{2R_1}"),
        S(r"ההפרש", r"זו האנרגיה שצריך להוסיף", r"E_1 - E_0 = GMm\left(\frac{1}{R} - \frac{1}{2R_1}\right) \approx 5.6 \times 10^{10}\,\text{J}"),
    ], r"$\approx 5.6 \times 10^{10}\,\text{J}$", key=r"5.6×10^10 J"),
  ],
  concepts=["החוק השלישי של קפלר", "אנרגיה של לוויין", "מעבר בין מסלולים", "שיגור"],
  summary=r"העברת לוויין למסלול גבוה יותר: הרדיוס מקפלר ומהפרש האנרגיות, זמן המחזור, והאנרגיה לשיגור מהקרקע.",
  review="הנחה שלי.\nמה לבדוק: רק לאשר.")
